def patch_bytes(target, raw):
    if target not in BASE_SHA256 or hashlib.sha256(raw).hexdigest() != BASE_SHA256[target]:
        raise ValueError('Atomic feedback patch requires exact RC8 source')
    newline = '\r\n' if b'\r\n' in raw else '\n'
    text = raw.decode('utf-8')
    for old, new in BLOCKS[target]:
        old, new = (old.replace('\n', newline), new.replace('\n', newline))
        if text.count(old) != 1:
            raise ValueError('Atomic feedback insertion anchor changed')
        text = text.replace(old, new, 1)
    return text.encode('utf-8')
